def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform rows and columns are the separators.
    sep_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}

    row_bands = []
    start = 0
    for r in sorted(sep_rows):
        if start < r:
            row_bands.append((start, r))
        start = r + 1
    if start < h:
        row_bands.append((start, h))

    col_bands = []
    start = 0
    for c in sorted(sep_cols):
        if start < c:
            col_bands.append((start, c))
        start = c + 1
    if start < w:
        col_bands.append((start, w))

    # The background is the most frequent non-separator color.
    separator_colors = {grid[r][0] for r in sep_rows}
    separator_colors.update(grid[0][c] for c in sep_cols)
    counts = {}
    for r in range(h):
        if r in sep_rows:
            continue
        for c in range(w):
            if c not in sep_cols and grid[r][c] not in separator_colors:
                color = grid[r][c]
                counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)

    result = []
    for r0, r1 in row_bands:
        row = []
        for c0, c1 in col_bands:
            unusual = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if unusual == 2 else background)
        result.append(row)
    return result
